class Meeting {
  private String title, date;
  private int time;                       // new field
  public Meeting() { }
  public Meeting(String title, String date, int time) { this.title=title; this.date=date; this.time=time; }
  public int getTime() { return time; }
  public void setTime(int time) { this.time = time; }
  public String getDate() { return date; }
  public String toString() { return title + " " + date + " " + time; }
}
ArrayList<Meeting> list = new ArrayList<>();
list.add(new Meeting("Budget", "01-03-2018", 900));
for (Meeting m : list) if (m.getDate().equals("01-03-2018")) m.setTime(1800);
for (Meeting m : list) System.out.println(m);

int[] a = {3, 8, 5, 1};
int target = 5; boolean found = false;
for (int i = 0; i < a.length; i++) {
  if (a[i] == target) { System.out.println("Value " + target + " is at index " + i); found = true; break; }
}
if (!found) System.out.println("Value not found");

public class Employee {
  private String firstName, lastName;
  private double monthlySalary;
  public Employee(String f, String l, double s) { firstName=f; lastName=l; setMonthlySalary(s); }
  public String getFirstName() { return firstName; }
  public void setFirstName(String f) { firstName = f; }
  public String getLastName() { return lastName; }
  public void setLastName(String l) { lastName = l; }
  public double getMonthlySalary() { return monthlySalary; }
  public void setMonthlySalary(double s) { monthlySalary = (s > 0) ? s : 0.0; }
}
